interface ToggleButtonActivationEvent {
  readonly type: 'activate';
  readonly pointerType: ButtonPointerType;
  readonly target: HTMLButtonElement;
}

interface ToggleButtonOwnProps {
  selected?: boolean;
  defaultSelected?: boolean;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  variant?: 'default' | 'quiet';
  preventFocusOnPress?: boolean;
  onChange?: (selected: boolean) => void;
  onActivate?: (event: ToggleButtonActivationEvent) => void;
}

interface ToggleButtonProps extends ToggleButtonOwnProps, Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, keyof ToggleButtonOwnProps | 'children' | 'className' | 'onClick'> {
  children?: React.ReactNode;
  className?: string;
}
